const fs = require('fs');

const [s, x] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(BigInt);

if (s < x || (s - x) % 2n !== 0n) {
  console.log('0');
} else {
  const common = (s - x) / 2n;

  if ((common & x) !== 0n) {
    console.log('0');
  } else {
    let bits = 0n;
    let value = x;

    while (value > 0n) {
      bits += value & 1n;
      value >>= 1n;
    }

    let answer = 1n << bits;
    if (common === 0n) answer -= 2n;

    console.log(answer.toString());
  }
}

